-- 건강 catalog는 이 migration이 정본이며 JSON은 배포용 투영이다.
-- [ASSUMPTION] 원본 SQL에서 단위 근거가 없는 지표는 legacy_unspecified로 보존하고 집계하지 않는다.
create table brain.health_catalog_v1 (metric text primary key, definition jsonb not null);
insert into brain.health_catalog_v1(metric,definition)
select item->>'metric',item from jsonb_array_elements($catalog$
[{"metric":"daily_metric.steps","type":"number","unit":"count","aggregations":["sum","mean"],"mappings":[{"table":"daily_metric","column":"steps","factor":1}],"basis":"원본 SQL 열 이름·주석 및 지표 의미","nullMeaning":"원본 결측·센티넬 또는 정규화 실패로 원인을 구별할 수 없음","meaning":"daily_metric의 steps 원본 값"},{"metric":"daily_metric.distance_m","type":"number","unit":"m","aggregations":["sum","mean"],"mappings":[{"table":"daily_metric","column":"distance_m","factor":1}],"basis":"원본 SQL 열 이름·주석 및 지표 의미","nullMeaning":"원본 결측·센티넬 또는 정규화 실패로 원인을 구별할 수 없음","meaning":"daily_metric의 distance_m 원본 값"},{"metric":"daily_metric.active_kcal","type":"number","unit":"kcal","aggregations":["sum","mean"],"mappings":[{"table":"daily_metric","column":"active_kcal","factor":1}],"basis":"원본 SQL 열 이름·주석 및 지표 의미","nullMeaning":"원본 결측·센티넬 또는 정규화 실패로 원인을 구별할 수 없음","meaning":"daily_metric의 active_kcal 원본 값"},{"metric":"daily_metric.moderate_intensity_s","type":"number","unit":"s","aggregations":["sum","mean"],"mappings":[{"table":"daily_metric","column":"moderate_intensity_s","factor":1}],"basis":"원본 SQL 열 이름·주석 및 지표 의미","nullMeaning":"원본 결측·센티넬 또는 정규화 실패로 원인을 구별할 수 없음","meaning":"daily_metric의 moderate_intensity_s 원본 값"},{"metric":"daily_metric.vigorous_intensity_s","type":"number","unit":"s","aggregations":["sum","mean"],"mappings":[{"table":"daily_metric","column":"vigorous_intensity_s","factor":1}],"basis":"원본 SQL 열 이름·주석 및 지표 의미","nullMeaning":"원본 결측·센티넬 또는 정규화 실패로 원인을 구별할 수 없음","meaning":"daily_metric의 vigorous_intensity_s 원본 값"},{"metric":"daily_metric.sleep_s","type":"number","unit":"s","aggregations":["sum","mean"],"mappings":[{"table":"daily_metric","column":"sleep_s","factor":1}],"basis":"원본 SQL 열 이름·주석 및 지표 의미","nullMeaning":"원본 결측·센티넬 또는 정규화 실패로 원인을 구별할 수 없음","meaning":"daily_metric의 sleep_s 원본 값"},{"metric":"daily_metric.deep_sleep_s","type":"number","unit":"s","aggregations":["sum","mean"],"mappings":[{"table":"daily_metric","column":"deep_sleep_s","factor":1}],"basis":"원본 SQL 열 이름·주석 및 지표 의미","nullMeaning