"number","unit":"bpm","aggregations":["mean"],"mappings":[{"table":"workout","column":"hr_avg","factor":1}],"basis":"원본 SQL 열 이름·주석 및 지표 의미","nullMeaning":"원본 결측·센티넬 또는 정규화 실패로 원인을 구별할 수 없음","meaning":"workout의 hr_avg 원본 값"},{"metric":"workout.hr_max","type":"number","unit":"bpm","aggregations":["mean"],"mappings":[{"table":"workout","column":"hr_max","factor":1}],"basis":"원본 SQL 열 이름·주석 및 지표 의미","nullMeaning":"원본 결측·센티넬 또는 정규화 실패로 원인을 구별할 수 없음","meaning":"workout의 hr_max 원본 값"},{"metric":"workout.bb_change","type":"number","unit":"score","aggregations":["mean"],"mappings":[{"table":"workout","column":"bb_change","factor":1}],"basis":"원본 SQL 열 이름·주석 및 지표 의미","nullMeaning":"원본 결측·센티넬 또는 정규화 실패로 원인을 구별할 수 없음","meaning":"workout의 bb_change 원본 값"},{"metric":"workout.session_no","type":"number","unit":"count","aggregations":[],"mappings":[{"table":"workout","column":"session_no","factor":1}],"basis":"원본 SQL 열 이름·주석 및 지표 의미","nullMeaning":"원본 결측·센티넬 또는 정규화 실패로 원인을 구별할 수 없음","meaning":"workout의 session_no 원본 값"},{"metric":"exercise_log.sets","type":"number","unit":"count","aggregations":["sum","mean"],"mappings":[{"table":"exercise_log","column":"sets","factor":1}],"basis":"원본 SQL 열 이름·주석 및 지표 의미","nullMeaning":"원본 결측·센티넬 또는 정규화 실패로 원인을 구별할 수 없음","meaning":"exercise_log의 sets 원본 값"},{"metric":"exercise_log.reps","type":"number","unit":"count","aggregations":["sum","mean"],"mappings":[{"table":"exercise_log","column":"reps","factor":1}],"basis":"원본 SQL 열 이름·주석 및 지표 의미","nullMeaning":"원본 결측·센티넬 또는 정규화 실패로 원인을 구별할 수 없음","meaning":"exercise_log의 reps 원본 값"},{"metric":"exercise_log.set_peak_hr_avg","type":"number","unit":"bpm","aggregations":["mean"],"mappings":[{"table":"exercise_log","column":"set_peak_hr_avg","factor":1}],"basis":"원본 SQL 열 이름·주석 및 지표 의미","nullMeaning":"원본 결측·센티넬 또는 정규화 실패로 원인을 구별할 수 없음","meaning":"exercise_log의 set_peak_hr_avg 원본 값"},{"metric":"exercise_log.rest_drop_avg","type":"number","unit":"legacy_unspecified","aggregations":[],"mappings":[{"table":"exercise_log","column":"rest_drop_avg","factor":1}],"basis":"원본 SQL에 단위 근거 없음","nullMeaning":"원본 결측·센티넬 또는 정규화 실패로 원인을 구별할 수 없음","meaning":"exercise_log의 rest_drop_avg 원본 값"},{"metric":"exercise_log.max_kg","type":"number","unit":"g","aggregations":["mean"],"mappings":[{"table":"exercise_log","column":"max_kg","factor":1000}],"basis":"원본 SQL 열 이름·주석 및 지표 의미","nullMeaning":"원본 결측·센티넬 또는 정규화 실패로 원인을 구별할 수 없음","meaning":"exercise_log의 max_kg 원본 값"},{"metric":"exercise_log.volume_kg","type":"number","unit":"g_repetitions","aggregations":["sum","mean"],"mappings":[{"table":"exercise_log","column":"volume_kg","factor":1000}],"basis":"원본 SQL 열 이름·주석 및 지표 의미","nullMeaning":"원본 결측·센티넬 또는 정규화 실패로 원인을 구별할 수 없음","meaning":"반복 부하의 합, 체중과 구별"}]
$catalog$::jsonb) item;
-- 0022의 열 순서와 기존 steps 생산자를 유지한다.
alter table brain.health_observations add column value_type text not null default 'number' check(value_type in ('number','text','json')),
 add column value_text text, add column value_json jsonb, add column catalog_version integer not null default 1 check(catalog_version=1),
 add column activity_id text, add column sub_identity text;
alter table brain.health_observations add constraint health_typed_value check (
 (value_type='number' and value_text is null and value_json is null and (value is null or value not in ('Infinity'::float8,'-Infinity'::float8,'NaN'::float8))) or
 (value_type='text' and value is null and value_json is null) or (value_type='json' and value is null and value_text is null and (value_json is null or jsonb_typeof(value_json) in ('object','array'))));
do $$ declare n text; begin select conname into n from pg_constraint where conrelid='brain.health_observations'::regclass and contype='u'; execute format('alter table brain.health_observations drop constraint %I',n); end $$;
alter table brain.health_observations add constraint health_storage_key unique nulls not distinct
 (source,dataset,account,original_table,original_key,metric,activity_id,sub_identity,local_date,observed_at,time_zone,normalization_version,revision);
create table brain.health_supported_versions (version integer primary key check(version>0));
insert into brain.health_supported_versions values (1),(2),(8);
create table brain.health_authority_rules (
 id uuid primary key, source text not null, account text not null, metric text, activity_id text,
 date_from date, date_to date, revision integer not null check(revision>0), datasets text[] not null,
 check(cardinality(datasets)>0), check(array_position(datasets,null) is null),
 check(date_from is null or date_to is null or date_from<=date_to),
 unique nulls not distinct(source,account,metric,activity_id,date_from,date_to,revision)
);
create trigger authority_immutable before update or delete on brain.health_authority_rules for each row execute function brain.reject_import_mutation();
create function brain.validate_health_observation() returns trigger language plpgsql security definer set search_path='' as $$
declare definition jsonb; oldrow brain.health_observations%rowtype;
begin
 select c.definition into definition from brain.health_catalog_v1 c where c.metric=case when new.metric='steps' then 'daily_metric.steps' else new.metric end;
 if definition is null or definition->>'type'<>new.value_type or definition->>'unit'<>new.unit then raise exception '건강 지표 타입 또는 단위 위반'; end if;
 perform pg_advisory_xact_lock(hashtextextended(jsonb_build_array(new.source,new.dataset,new.account,new.original_table,new.original_key,new.metric,new.activity_id,new.sub_identity,new.local_date,extract(epoch from new.observed_at),new.time_zone,new.normalization_version,new.revision)::text,0));
 select * into oldrow from brain.health_observations h where h.source=new.source and h.dataset=new.dataset and h.account is not distinct from new.account and h.original_table=new.original_table and h.original_key=new.original_key and h.metric=new.metric and h.activity_id is not distinct from new.activity_id and h.sub_identity is not distinct from new.sub_identity and h.local_date is not distinct from new.local_date and h.observed_at is not distinct from new.observed_at and h.time_zone is not distinct from new.time_zone and h.normalization_version=new.normalization_version and h.revision=new.revision;
 if found then
   if (oldrow.value,oldrow.value_type,oldrow.value_text,oldrow.value_json,oldrow.unit,oldrow.fetched_at,oldrow.account_confirmed,oldrow.time_zone_missing,oldrow.catalog_version) is distinct from (new.value,new.value_type,new.value_text,new.value_json,new.unit,new.fetched_at,new.account_confirmed,new.time_zone_missing,new.catalog_version) then raise exception '건강 보관키 payload 충돌'; end if;
   return null;
 end if;
 return new;
end $$;
create trigger validate_health before insert on brain.health_observations for each row execute function brain.validate_health_observation();

-- 각 논리 키에 대한 전체 provenance와 판정. 원문 동률은 버전 선택 전에 검사한다.
create view brain.health_resolution_v1 as
with keys as (
 select distinct source,account,metric,activity_id,sub_identity,local_date,observed_at,time_zone from brain.health_observations
), decisions as (
 select k.*, a.id as authority_id,a.revision as authority_version,a.datasets,
   (select count(distinct h.dataset) from brain.health_observations h where (h.source,h.account,h.metric,h.activity_id,h.sub_identity,h.local_date,h.observed_at,h.time_zone) is not distinct from (k.source,k.account,k.metric,k.activity_id,k.sub_identity,k.local_date,k.observed_at,k.time_zone)) as dataset_count,
   (select bool_and(h.account_confirmed) from brain.health_observations h where (h.source,h.account,h.metric,h.activity_id,h.sub_identity,h.local_date,h.observed_at,h.time_zone) is not distinct from (k.source,k.account,k.metric,k.activity_id,k.sub_identity,k.local_date,k.observed_at,k.time_zone)) as confirmed,
   (select array_agg(h.id order by h.id) from brain.health_observations h where (h.source,h.account,h.metric,h.activity_id,h.sub_identity,h.local_date,h.observed_at,h.time_zone) is not distinct from (k.source,k.account,k.metric,k.activity_id,k.sub_identity,k.local_date,k.observed_at,k.time_zone)) as all_ids
 from keys k left join lateral (
   select r.* from brain.health_authority_rules r where r.source=k.source and r.account=k.account and (r.metric is null or r.metric=k.metric) and (r.activity_id is null or r.activity_id=k.activity_id) and (r.date_from is null or k.local_date>=r.date_from) and (r.date_to is null or k.local_date<=r.date_to)
   order by ((r.metric is not null)::int+(r.activity_id is not null)::int+(r.date_from is not null)::int+(r.date_to is not null)::int) desc,r.revision desc,r.id limit 1
 ) a on true
), selected_dataset as (
 select d.*, case when d.authority_id is null and d.dataset_count=1 then
   (select h.dataset from brain.health_observations h where h.id=d.all_ids[1])
 else (select x.dataset from unnest(d.datasets) with ordinality x(dataset,ord) where exists(select 1 from brain.health_observations h where h.id=any(d.all_ids) and h.dataset=x.dataset) order by x.ord limit 1) end as dataset
 from decisions d
), latest as (
 select d.*, (select max(h.fetched_at) from brain.health_observations h where h.id=any(d.all_ids) and h.dataset=d.dataset) as fetched_at from selected_dataset d
), revisions as (
 select d.*, (select count(distinct h.revision) from brain.health_observations h where h.id=any(d.all_ids) and h.dataset=d.dataset and h.fetched_at=d.fetched_at) as revision_count,
 (select array_agg(h.id order by h.id) from brain.health_observations h where h.id=any(d.all_ids) and h.dataset=d.dataset and h.fetched_at=d.fetched_at) as observed_ids,
 (select max(h.normalization_version) from brain.health_observations h join brain.health_supported_versions v on v.version=h.normalization_version where h.id=any(d.all_ids) and h.dataset=d.dataset and h.fetched_at=d.fetched_at) as version
 from latest d
), candidates as (
 select d.*, (select array_agg(h.id order by h.id) from brain.health_observations h where h.id=any(d.observed_ids) and h.normalization_version=d.version) as candidate_ids,
 (select count(distinct jsonb_build_array(h.value_type,h.value,h.value_text,h.value_json)) from brain.health_observations h where h.id=any(d.observed_ids) and h.normalization_version=d.version) as value_count from revisions d
), reasons as (
 select d.*, case when account is null or not confirmed then 'account_unconfirmed' when local_date is not null and time_zone is null then 'timezone_unconfirmed' when authority_id is null and dataset_count>1 then 'dataset_ambiguous' when dataset is null then 'dataset_unselected' when revision_count>1 then 'revision_ambiguous' when version is null then 'version_unsupported' when value_count>1 then 'value_ambiguous' else null end as reason from candidates d
)
select source,account,metric,activity_id,sub_identity,local_date,observed_at,time_zone,authority_id,authority_version,dataset,reason,
 case when reason is null then candidate_ids[1] else null end as current_id,
 case when reason in ('revision_ambiguous','version_unsupported') then observed_ids when reason='value_ambiguous' or reason is null then candidate_ids else array[]::uuid[] end as selected_ids,
 all_ids, array(select id from unnest(all_ids) id where not (id=any(coalesce(case when reason in ('revision_ambiguous','version_unsupported') then observed_ids when reason='value_ambiguous' or reason is null then candidate_ids else array[]::uuid[] end,array[]::uuid[]))) order by id) as unselected_ids from reasons;
drop view brain.health_current_v1;
create view brain.health_current_v1 as select h.* from brain.health_observations h join brain.health_resolution_v1 r on r.current_id=h.id;
create function brain.health_aggregate_v1(metric_name text,operation text,source_name text default null,activity_name text default null) returns double precision language plpgsql stable set search_path='' as $$
declare def jsonb; result double precision;
begin
 select definition into def from brain.health_catalog_v1 where metric=case when metric_name='steps' then 'daily_metric.steps' else metric_name end;
 if def is null or operation is null or not (def->'aggregations' ? operation) then raise exception 'HEALTH_AGGREGATION_NOT_ALLOWED'; end if;
 select case when operation='sum' then sum(value) else avg(value) end into result from brain.health_current_v1 where metric=metric_name and value_type='number' and unit=def->>'unit' and (source_name is null or source=source_name) and (activity_name is null or activity_id=activity_name);
 return result;
end $$;
revoke all on brain.health_catalog_v1,brain.health_supported_versions,brain.health_authority_rules,brain.health_resolution_v1,brain.health_current_v1 from public;
revoke all on function brain.health_aggregate_v1(text,text,text,text) from public;
grant select on brain.health_catalog_v1,brain.health_supported_versions,brain.health_authority_rules,brain.health_resolution_v1,brain.health_current_v1 to brain_app;
grant insert on brain.health_supported_versions,brain.health_authority_rules to brain_app;
grant execute on function brain.health_aggregate_v1(text,text,text,text) to brain_app;
do $$ declare r record; begin
 for r in select rolname from pg_roles where rolname like 'brain\_ext\_%' escape '\' and shobj_description(oid,'pg_authid')='second-brain extension:' || current_database() loop
  execute format('grant insert (value_type,value_text,value_json,catalog_version,activity_id,sub_identity) on brain.health_observations to %I',r.rolname);
  execute format('grant select on brain.health_catalog_v1 to %I',r.rolname);
 end loop;
end $$;
